import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.EducationResourceURI{Resource: protocol.EducationSharedResourceURI{ButtonName: "btn", LinkURI: "https://x"}}
RESOURCE = bytes.fromhex("0362746e0968747470733a2f2f78")

# generated by gophertunnel b8bd735:
# &packet.EducationResourceURI{}
EMPTY = bytes.fromhex("0000")

GOLDENS = [
    pytest.param(
        v2225.EduUriResourcePacket(
            edu_shared_uri_resource=v2225.EduSharedUriResource(button_name="btn", link_uri="https://x")
        ),
        RESOURCE,
        id="resource",
    ),
    pytest.param(v2225.EduUriResourcePacket(), EMPTY, id="empty"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_edu_uri_resource_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_edu_uri_resource_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
